/** Kısa fiyat metni: "Ücretsiz plan var · 20 $/ay'dan başlıyor" */
export function priceShort(t) {
  const f = t.free ? freeLabel[t.free] : '';
  const p = t.price?.from ? `${Number.isInteger(t.price.from) ? t.price.from : t.price.from.toLocaleString('tr-TR')} $/ay'dan` : '';
  return [f, p].filter(Boolean).join(' · ') || 'Fiyat: resmi sayfada';
}
